 styles.\n//** Background color for `<body>`.\n$body-bg:               #fff !default;\n//** Global text color on `<body>`.\n$text-color:            $gray-dark !default;\n//** Global textual link color.\n$link-color:            $brand-primary !default;\n//** Link hover color set via `darken()` function.\n$link-hover-color:      darken($link-color, 15%) !default;\n//** Link hover decoration.\n$link-hover-decoration: underline !default;\n\nsvg.dot {\n  vertical-align: middle;\n  height:30px;\n}\n\n.darr{\n    width:25px;\n    text-align:center;\n}\n.scroll-down {\n  position: absolute;\n  left: 50%;\n  margin-left: -20px;\n  width: 40px;\n  height: 40px;\n  bottom: 35px;\n  padding-left: 7px;\n  cursor: pointer;\n  z-index: 2;\n  color: #fff;\n  -webkit-box-sizing: border-box;\n  -moz-box-sizing: border-box;\n  box-sizing: border-box;\n}\n.scroll-down.svg svg {\n  width: 25px;\n  opacity: 1;\n  -webkit-transition: opacity .5s;\n  -moz-transition: opacity .5s;\n  -ms-transition: opacity .5s;\n  -o-transition: opacity .5s;\n  transition: opacity .5s;\n}\n.scroll-down.svg .stroke {\n  stroke: #fff;\n}\n.scroll-down.svg .scroller {\n  fill: #fff;\n  -webkit-animation: updown 1s infinite;\n  -moz-animation: updown 1s infinite;\n  -o-animation: updown 1s infinite;\n  animation: updown 1s infinite;\n}\n\n@-webkit-keyframes updown {\n    0% {\n        -webkit-transform: translate(0, 0);\n        transform: translate(0, 0)\n    }\n    50% {\n        -webkit-transform: translate(0, 5px);\n        transform: translate(0, 5px)\n    }\n    100% {\n        -webkit-transform: translate(0, 0);\n        transform: translate(0, 0)\n    }\n}\n@-moz-keyframes updown {\n    0% {\n        -moz-transform: translate(0, 0);\n        transform: translate(0, 0)\n    }\n    50% {\n        -moz-transform: translate(0, 5px);\n        transform: translate(0, 5px)\n    }\n    100% {\n        -moz-transform: translate(0, 0);\n        transform: translate(0, 0)\n    }\n}\n@-o-keyframes updown {\n    0% {\n        -o-transform: translate(0, 0);\n        transform: translate(0, 0)\n    }\n    50% {\n        -o-transform: translate(0, 5px);\n        transform: translate(0, 5px)\n    }\n    100% {\n        -o-transform: translate(0, 0);\n        transform: translate(0, 0)\n    }\n}\n@keyframes updown {\n    0% {\n        -webkit-transform: translate(0, 0);\n        transform: translate(0, 0)\n    }\n    50% {\n        -webkit-transform: translate(0, 5px);\n        transform: translate(0, 5px)\n    }\n    100% {\n        -webkit-transform: translate(0, 0);\n        transform: translate(0, 0)\n    }\n}\n\n\n.logo__background-color {\n    fill: $color-white;\n    transition: fill .6s;\n    &.alt {\n        fill: $brand-tertiary;\n    }\n}\n\n.nav-wrapper{\n    padding-left:20px;\n    padding-right:30px;\n}\n.navbar__hidden--top {\n    background-color: #ffffff;\n    overflow: hidden;\n    color: $body-bg;\n    -webkit-box-shadow: inset 0px -5px 22px 0px rgba(209, 209, 209, 0.23);\n    -moz-box-shadow: inset 0px -5px 22px 0px rgba(209, 209, 209, 0.23);\n    box-shadow: inset 0px -5px 22px 0px rgba(209, 209, 209, 0.23);\n    a,\n    a:active,\n    a:visited {\n        cursor: pointer;\n        color: $gray-darker;\n        font-size: .8em;\n            font-family: \"AvenirLTStdBlack\";\n    }\n    a:hover {\n        color: $link-hover-color;\n    }\n    @media (max-width: 768px) {\n        a {\n            font-size: .9em\n        }\n    }\n    ul {\n        margin: 0 auto 0 auto !important;\n        padding-top: 25px !important;\n        padding-bottom: 20px !important;\n      \n        \n        li {\n            display: inline;\n            cursor: pointer;\n            margin-right: 20px;\n        }\n        @media (max-width: 768px) {\n            li {\n                margin-right: 10px;\n            }\n        }\n    }\n    @media (max-width: 768px) {\n        ul {\n            display: block;\n            width: 100%;\n            text-align: center;\n            padding-left: 0;\n            margin-left: 0;\n        }\n    }\n}\n.social-media{\n    display:inline;\n    cursor:default;\n    position:absolute;\n    right:15px;\n    top:19px;\n    .social-icon{\n        fill: $color-white;\n        transition: fill .6s;\n        &.alt {\n            fill: $brand-tertiary;\n        }\n    }\n    #Capa_1{\n        position:relative;\n        top:0px;\n    }\n    #open-icon-text{\n        display:none;\n        position:absolute;\n        opacity:.9;\n        top:-10px;\n        left:-1px;\n        z-index:200;\n        font-size:9px;\n        font-family: \"AvenirLTStdLight\";\n        color:#fff;\n    }//end open-icon-text\n    #open-icon{\n        width:20px;\n        height:20px;\n        cursor:pointer;\n        position:absolute;\n        top:0;\n        opacity:.8;\n        z-index:200;\n        &:hover{\n            opacity:.9;\n        }\n    }//end open-icon-text\n    #drawer{\n        display:inline-block;\n        overflow:hidden;\n        position:relative;\n        right:70px;\n        #slide{\n            position:relative;\n            z-index:200;\n            left:100px;\n            top:0px;\n            background-color: transparent;\n            transition: left .3s;\n                a{\n                    height:20px;\n                    width:20px;\n                }\n                &.expand{\n                    left:0;\n                }\n                .icon{\n                    height:20px;\n                    width:20px;\n                    margin-left:7px;\n                    position:relative;\n                    top:-1px;\n                    display:inline-block;\n                    &:hover{\n                        opacity:.8;\n                    }\n                }\n                ._lg{\n                    width:27px;\n                }\n                .svgicon{\n                    fill:#fff;\n                    &.alt{\n                        fill:$brand-tertiary;\n                    }\n                }\n        }\n    }\n    \n}//end social\n\n\n#main {\n    position: relative;\n    height: 100vh;\n    width: 100vw;\n    .main__image--top {\n        position: absolute;\n        top: 0;\n        left: 0;\n        z-index: 100;\n        width: 100vw;\n        height: 100vh;\n        background: url('./../../assets/hero__img--home.webp') no-repeat center center fixed;\n        -webkit-background-size: cover;\n        -moz-background-size: cover;\n        -o-background-size: cover;\n        background-size: cover;\n    }\n\n\n    .main__image--top--overlay {\n        position: absolute;\n        top: 0;\n        left: 0;\n        z-index: 300;\n        width: 100vw;\n        height: 100vh;\n        background-color: black;\n        opacity: .5;\n        pointer-events: none;\n    }\n    .main__navbar {\n        position: fixed;\n        width: 100%;\n        z-index: 1000;\n        background-color: transparent;\n        transition: background-color .6s;\n        /* Or border-top-color */\n        ul{\n            padding: 0;\n            margin-top: 25px;\n            margin-bottom: 15px;\n            float: right;\n            li {\n                display: inline;\n                cursor: pointer;\n            }\n        }\n        .main__navbar--logo--container {\n            display: inline;\n            a {\n                font-size: 30px;\n                font-family: \"AvenirLTStdBlack\";\n                position: relative;\n            }\n            svg {\n                height: 40px;\n                width: auto;\n                margin-top: 15px;\n                margin-left: 5px;\n                opacity:.9;\n            }\n        }\n        .main__navbar--item--wrapper {\n            position: relative;\n            height: 27px;\n            width: 23px;\n            cursor: pointer;\n            display: inline-block;\n            color: $color-white;\n            .main__navbar-item {\n                font-size: 30px;\n            }\n            i {\n                font-size: 30px;\n            }\n        }\n    }\n    .main__navbar.alt {\n        background-color: $color-white;\n        box-shadow: 0px 0px 5px 0px rgba(85, 85, 85, 0.25);\n    }\n    .main__masthead {\n        .main__masthead--content {\n            height: 100vh;\n            overflow:hidden;\n            .sd-container{\n                position:absolute;\n                bottom:30px;\n                z-index:200;\n                left:50vw;\n                opacity:.9;\n                .scrolldown{\n                    z-index:200;\n                    position:absolute;\n                    bottom:0;\n                    width:1px;\n                    height:0;\n                    background-color:#fff;\n                    transition: height 1.5s;\n                    transition-delay: 1s;\n                    &.grow{\n                        height:200px;\n                    }\n                }\n                .dot{\n                    opacity:0;\n                    z-index:200;\n                    cursor:pointer;\n                    position:relative;\n                    transition: opacity .5s;\n                    transition-delay: .5s;\n                    &.show{\n                        opacity:1;\n                    }\n                    &:hover{\n                        filter: brightness(0.6) sepia(1) hue-rotate(300deg) saturate(9);\n                    }\n                }\n                .scroll-text{\n                    position:absolute;\n                    color:white;\n                    z-index:200;\n                    bottom:100px;\n                    top:70px;\n                    transform: rotate(-90deg);\n                    font-family: 'proxima_novablack';\n                    font-size:13px;\n                    right:2px;;\n                    width:100px;\n                    opacity:0;\n                    transition: opacity .5s;\n                    transition-delay: 2.5s;\n                    &.show{\n                        opacity:1;\n                    }\n                }\n            }\n        }\n        .text__about--link {\n            position: absolute;\n            z-index: 400;\n            bottom: 30px;\n            left: 60px;\n            color: $color-white;\n            a {\n                color: $color-white;\n                font-size: 12px;\n            }\n        }\n    }\n    #main__navbar--burger--wrapper {\n        opacity:.9;\n        &:hover{\n            opacity:1;\n        }\n        .flip--wrapper {\n            position: relative;\n            min-height: 2px;\n        }\n        .burger__bar {\n            height: 2px;\n            background-color: $color-white;\n            /* Or border-top-color */\n            &.burger__bar--top {\n                width: 30px;\n                margin-bottom: 5px;\n                -webkit-transition: .5s ease-in-out;\n                -moz-transition: .5s ease-in-out;\n                -o-transition: .5s ease-in-out;\n                transition: .5s ease-in-out;\n                &.open {\n                    transform: scale(0);\n                }\n            }\n            &.burger__bar--bottom {\n                width: 30px;\n                margin-top: 5px;\n                -webkit-transition: .5s ease-in-out;\n                -moz-transition: .5s ease-in-out;\n                -o-transition: .5s ease-in-out;\n                transition: .5s ease-in-out;\n                &.open {\n                    transform: scale(0);\n                }\n            }\n            &.burger__bar--top--flip {\n                width: 30px;\n                position: absolute;\n                top: 0;\n                left: 0;\n                -webkit-transition: .5s ease-in-out;\n                -moz-transition: .5s ease-in-out;\n                -o-transition: .5s ease-in-out;\n                transition: .5s ease-in-out;\n                &.open {\n                   